import sys
import numpy as np

def main():
    import sys
    import numpy as np

    def readints():
        return list(map(int, sys.stdin.readline().split()))

    n, m = readints()
    room_status = readints()
    switches = []

    for _ in range(m):
        line = readints()
        x = line[0]
        rooms = line[1:]
        switches.append(rooms)

    # Create the matrix representation of the problem
    matrix = np.zeros((m, n), dtype=int)

    for i, rooms in enumerate(switches):
        for room in rooms:
            matrix[i, room-1] = 1

    # Create the augmented matrix
    augmented_matrix = np.column_stack((matrix, room_status))

    # Perform Gaussian elimination
    augmented_matrix = augmented_matrix.astype(float)
    for i in range(m):
        # Find the pivot row
        max_row = i
        for j in range(i+1, m):
            if abs(augmented_matrix[j, i]) > abs(augmented_matrix[max_row, i]):
                max_row = j
        # Swap rows
        augmented_matrix[[i, max_row]] = augmented_matrix[[max_row, i]]

        # Make the pivot element 1
        pivot = augmented_matrix[i, i]
        if pivot != 0:
            augmented_matrix[i] /= pivot

        # Eliminate the pivot column in other rows
        for j in range(m):
            if j != i:
                factor = augmented_matrix[j, i]
                augmented_matrix[j] -= factor * augmented_matrix[i]

    # Check for consistency
    rank = np.linalg.matrix_rank(matrix)
    augmented_rank = np.linalg.matrix_rank(augmented_matrix)

    if rank == augmented_rank:
        print("YES")
    else:
        print("NO")

if __name__ == "__main__":
